import 'package:freezed_annotation/freezed_annotation.dart';

part 'capture_ui.freezed.dart';

/// The controls for choosing a capture (rule R5): the [selectedSum] of the
/// dice picked so far, the [maxSum] a capture may reach, and whether the
/// pick can be confirmed.
///
/// Plain data generated by freezed (docs/adr/0011, docs/adr/0015).
@freezed
abstract class CaptureUi with _$CaptureUi {
  const factory CaptureUi({
    required int selectedSum,
    required int maxSum,
    required bool canConfirm,
  }) = _CaptureUi;
}
